-- 이웅 교수 (2026년 부임, 부교수) — 옛 홈페이지 02_01_view.php?idx=54 에서 가져옴
-- 사진은 옛 사이트 것이 315x334 로 작아 넣지 않았다. 고해상도 받으면 photo_url 만 채우면 된다.
delete from faculty where name_ko = '이웅';
insert into faculty (name_ko, name_en, title_ko, title_en, email, tel, lab_ko, lab_en, lab_url,
                     building, room, photo_url, keywords, research_ko, bio_ko, field, is_emeritus, sort_order)
  values ('이웅', 'Ung Lee', '부교수', 'Associate Professor', 'ulee@sogang.ac.kr', '02-705-8476', '청정에너지 공정시스템 연구실(Clean Energy Process Systems Laboratory)', 'Clean Energy Process Systems Laboratory', 'https://cepl.sogang.ac.kr/', 'CY', '414', null, 'Process Systems Engineering, CO₂ Capture & Utilization, Machine Learning for Process Design, Multiscale Reactor Design', '<p class="text-lg font-semibold">Process Systems Engineering, Machine Learning for Process Design, Microkinetic Modeling and Multiscale Reactor Design, CO₂ Capture and Utilization (CCUS), Techno-Economic and Life Cycle Assessment</p><p>Machine Learning-Aided Optimal Process Design<br>A chemical process can be built in a number of ways — flowsheet layout, operating conditions, solvent, catalyst — and every choice multiplies the others. The space is far too large to search by intuition, and far too large to simulate one case at a time. We therefore write the whole space down as a superstructure: one model that contains every candidate design, and search it with machine learning. Surrogate models replace rigorous simulations inside the optimization loop; Bayesian optimization and active learning pick the next experiment to run; neural screening narrows a billion candidate molecules to a few. Process, solvent and catalyst are designed together rather than one after another, and an experimental campaign reaches the optimum in a fraction of the runs.</p><p>Microkinetic Modeling and Multiscale Reactor Design<br>A process model is only as good as the chemistry beneath it, so we start at the bottom. We build microkinetic models from elementary reaction steps and carry them into computational fluid dynamics of the reactor, then into the flowsheet, and finally into economics and life cycle assessment — one unbroken chain from an activation barrier to a production cost per ton. We have built it for CO₂ hydrogenation to formic acid and methanol, for Fischer–Tropsch microchannel reactors, and for electrochemical CO₂ reduction cells. We also run the chain backwards: explainable AI reads experimental electrochemical data and tells us which descriptors govern catalyst activity and degradation, and those descriptors go straight back into electrode and reactor design.</p><p>Carbon Capture, Utilization and Clean Energy Systems<br>Making a laboratory reaction compete on cost is a systems problem, and we take it the whole way. We model and screen capture solvents by computation and by experiment, and study reactive capture, which converts CO₂ directly and skips the energy-intensive regeneration step. We develop electrochemical and thermocatalytic routes to formic acid, methanol, carbon monoxide and olefins; techno-economic and life cycle assessment then decides which routes deserve to be scaled. Several of these lines have reached pilot-scale demonstration and technology transfer to industry.</p>', '<h3>학력</h3><ul><li>Purdue University 화학공학 학사 (2008)</li><li>서울대학교 화학생물공학부 공학박사 (2014)</li></ul><h3>경력</h3><ul><li>2017–2026 선임연구원·책임연구원, 한국과학기술연구원(KIST) 청정에너지연구센터</li><li>2020–2022 KIST Young Fellow</li><li>2023–2026 학연교수, 고려대학교 에너지환경대학원</li><li>2023 (사)한국공업화학회 화학공정분과회 위원장</li></ul><h3>대표 논문</h3><ul><li>“Reactive capture and electro-conversion of triethylamine-captured CO₂ to high-concentration formic acid”, <i>Joule</i> (2026), in press.</li><li>“Discovering the origin of catalyst performance and degradation of electrochemical CO₂ reduction through interpretable machine learning”, <i>ACS Catalysis</i> 15 (2025) 2158–2170.</li><li>“Accelerating the net-zero economy with CO₂-hydrogenated formic acid production: Process development and pilot plant demonstration”, <i>Joule</i> 8 (2024) 693–713.</li><li>“Electrochemically initiated synthesis of ethylene carbonate from CO₂”, <i>Nature Synthesis</i> 3 (2024) 846–857.</li><li>“Toward economical application of carbon capture and utilization technology with near-zero carbon emission”, <i>Nature Communications</i> 13 (2022) 7482.</li><li>“Catalyst-electrolyte interface chemistry for electrochemical CO₂ reduction”, <i>Chemical Society Reviews</i> 49 (2020) 6632–6665.</li><li>“General technoeconomic analysis for electrochemical coproduction coupling carbon dioxide reduction with organic oxidation”, <i>Nature Communications</i> 10 (2019) 5193.</li></ul>', null, false, 18);
